// LAMPJACK — a desk lamp that floats on a propeller and fights with its own coiled cord.
// Drawn fighter exemplar: a plain ES module, no imports, everything from `api`.
// Fighter space: +x is the facing direction, +y is DOWN, the origin is at the feet.
// Frames are 1-based within a move. Hitboxes: hb([first,last], x, y, r, damage, angle, base, growth, extra)
// and cap(...) for a capsule from (x,y) to (x2,y2). Angle 0 launches away from the attacker, 90 up,
// 270 down (a spike), 180 pulls the victim toward the attacker.
export default function make(api) {
  const { hb, cap, key, mv, throwMove, spawnProjectile, spriteAnims, spriteLoops, B, sign } = api;

  const stats = {
    weight: 78, walk: 3.2, run: 5.6, dashInit: 6.5, airSpeed: 4.2, airAccel: 0.2,
    fallSpeed: 6.5, fastFall: 10, gravity: 0.4, shortHop: 8, fullHop: 13, doubleJump: 12,
    jumps: 3, wallJump: false, traction: 0.5, height: 120, width: 60, crouchHeight: 84, landLag: 4, ledgeReach: 40,
  };

  // Poses for a drawn fighter are squash/stretch/lean/offset on the whole cell (the cell itself is the drawing).
  const P = (extra) => ({ a: {}, ...extra });
  const rest = P({});
  // A pose track that leans into a strike then settles: windup, extend, hold, recover.
  const strike = (total, hit, lean, extra = {}) => [
    key(0, P({ rot: -lean * 0.5, sx: 0.96, sy: 1.04, ...extra })),
    key(hit, P({ rot: lean, sx: 1.1, sy: 0.94, ...extra })),
    key(Math.min(total - 1, hit + 6), P({ rot: lean * 0.8, sx: 1.04, sy: 0.98, ...extra })),
    key(total, rest),
  ];

  const CORD = { fx: "energy" };
  const HEAVY = { fx: "heavy" };
  const moves = {
    // ground normals: the cord flicks out, the shade leans with it
    jab1: mv("jab1", 20, [cap([4, 6], 30, -60, 84, -60, 14, 4, 60, 25, 55, CORD)], strike(20, 4, 8), { iasa: 15, next: "jab2", nextFrom: 7 }),
    jab2: mv("jab2", 24, [cap([5, 7], 30, -64, 96, -64, 15, 5, 50, 30, 70, CORD)], strike(24, 5, 10), { iasa: 18 }),
    ftilt: mv("ftilt", 32, [cap([9, 12], 20, -70, 130, -70, 16, 10, 40, 40, 85, CORD)], strike(32, 9, 14)),
    utilt: mv("utilt", 30, [cap([7, 11], -30, -150, 40, -175, 22, 9, 90, 35, 90, CORD)], strike(30, 7, -6, { dy: -6 })),
    dtilt: mv("dtilt", 26, [cap([6, 9], 10, -14, 110, -10, 14, 8, 30, 30, 65, CORD)], strike(26, 6, 6, { sy: 0.85, dy: 10 })),
    dashAttack: mv("dashAttack", 40, [cap([9, 16], 0, -80, 80, -70, 30, 11, 55, 55, 65, HEAVY)], strike(40, 9, 24), { motion: [[1, 7, 0], [12, 4, 0], [20, 1, 0]] }),
    // smashes: the cord cracks like a whip; the tip is a sweetspot
    fsmash: mv("fsmash", 52, [
      cap([16, 19], 40, -70, 160, -60, 18, 18, 38, 45, 95, { fx: "tip", priority: 0 }),
      cap([16, 21], 20, -70, 100, -66, 22, 13, 40, 40, 80, { ...CORD, priority: 1 }),
    ], strike(52, 16, 22), { smash: true }),
    usmash: mv("usmash", 50, [cap([15, 20], -50, -170, 50, -190, 30, 16, 88, 40, 100, HEAVY)], strike(50, 15, -8, { dy: -12, sy: 1.12 }), { smash: true }),
    dsmash: mv("dsmash", 54, [
      cap([16, 19], 10, -20, 120, -20, 22, 15, 28, 45, 88, { ...HEAVY, group: 0 }),
      cap([22, 25], -10, -20, -120, -20, 22, 15, 28, 45, 88, { ...HEAVY, group: 1 }),
    ], [key(0, P({ sy: 0.9 })), key(16, P({ rot: 20, sx: 1.15, sy: 0.8 })), key(22, P({ rot: -20, sx: 1.15, sy: 0.8 })), key(54, rest)], { smash: true }),
    // aerials: floaty, disjointed
    nair: mv("nair", 36, [cap([5, 22], -60, -70, 60, -70, 38, 9, 55, 30, 65, { ...CORD, group: 0 })], [key(0, rest), key(6, P({ rot: 90 })), key(24, P({ rot: 420 })), key(36, P({ rot: 720 }))], { aerial: true, landingLag: 10 }),
    fair: mv("fair", 40, [cap([10, 14], 20, -60, 120, -50, 22, 13, 42, 40, 88, CORD)], strike(40, 10, 16), { aerial: true, landingLag: 14 }),
    bair: mv("bair", 34, [cap([8, 11], -20, -80, -130, -90, 20, 14, 35, 45, 90, CORD)], strike(34, 8, -18), { aerial: true, landingLag: 12, cell: "atk-fwd", cellFlip: true }),
    uair: mv("uair", 34, [cap([8, 12], -40, -160, 40, -175, 26, 11, 85, 35, 85, CORD)], strike(34, 8, -4, { dy: -8 }), { aerial: true, landingLag: 10 }),
    dair: mv("dair", 46, [
      cap([16, 18], -14, 6, 14, 6, 26, 14, 270, 25, 90, { ...HEAVY, spike: true, priority: 0 }),
      cap([19, 24], -14, 6, 14, 6, 24, 10, 60, 30, 75, { ...HEAVY, priority: 1 }),
    ], [key(0, P({ sy: 1.08 })), key(15, P({ sy: 0.86, sx: 1.12, dy: 6 })), key(26, P({ sy: 0.94 })), key(46, rest)], { aerial: true, landingLag: 20, hover: [10, 15] }),
    // grabs: the hook snags them
    grab: mv("grab", 36, [hb([7, 9], 60, -70, 26, 0, 0, 0, 0, { grab: true })], strike(36, 7, 12), { isGrab: true }),
    dashGrab: mv("dashGrab", 42, [hb([9, 11], 74, -70, 28, 0, 0, 0, 0, { grab: true })], strike(42, 9, 20), { isGrab: true, motion: [[1, 5, 0], [9, 0, 0]] }),
    pummel: mv("pummel", 16, [], [key(0, P({ rot: 6 })), key(6, P({ rot: 14, sx: 1.06 })), key(16, P({ rot: 6 }))]),
    fthrow: throwMove("fthrow", 32, 14, 9, 45, 55, 70, [key(0, P({ rot: 6 })), key(14, P({ rot: 26, sx: 1.1 })), key(32, rest)]),
    bthrow: throwMove("bthrow", 40, 18, 11, 40, 60, 78, [key(0, P({ rot: 6 })), key(18, P({ rot: -40 })), key(40, rest)]),
    uthrow: throwMove("uthrow", 36, 16, 8, 90, 65, 90, [key(0, P({ rot: 6 })), key(16, P({ dy: -14, sy: 1.14 })), key(36, rest)]),
    dthrow: throwMove("dthrow", 40, 20, 7, 68, 45, 40, [key(0, P({ rot: 6 })), key(20, P({ sy: 0.8, sx: 1.15, dy: 16 })), key(40, rest)]),
    // BULB FLASH: hold to charge, then a blinding multi-hit burst around the shade
    nspecial: mv("nspecial", 64, [hb([26, 38], 0, -90, 62, 3, 80, 20, 40, { ...CORD, rehit: 4 }), hb([39, 41], 0, -90, 76, 8, 60, 45, 95, { fx: "heavy", group: 1 })], [key(0, P({ sy: 0.94 })), key(25, P({ sy: 0.88, sx: 1.08 })), key(26, P({ sy: 1.16, sx: 1.12 })), key(42, P({ sy: 1.02 })), key(64, rest)], { hook: "flash", cell: "atk-up", fx: "quake" }),
    // HOOK CAST: throw the hook; it drags whoever it catches back toward the lamp
    sspecial: mv("sspecial", 44, [], strike(44, 12, 18), { hook: "cast" }),
    // PROPELLER: a long, steerable lift. Helpless after.
    uspecial: mv("uspecial", 58, [cap([4, 10], -30, -100, 30, -100, 36, 7, 80, 40, 60, CORD)], [key(0, P({ sy: 0.88, sx: 1.1 })), key(4, P({ sy: 1.14, sx: 0.92 })), key(30, P({ rot: 6 })), key(58, P({ rot: -10 }))], { hook: "lift", helpless: true, ledgeOk: true, cell: "jump" }),
    // LIGHTS OUT: switch off and wait; anything that hits the dark lamp gets the cord back at 1.5x
    dspecial: mv("dspecial", 40, [], [key(0, rest), key(4, P({ sy: 0.9, sx: 1.05 })), key(24, P({ sy: 0.9, sx: 1.05 })), key(40, rest)], { counter: { frames: [4, 24], move: "blackoutStrike", mul: 1.5, min: 8 }, cell: "block", fx: "guard" }),
    blackoutStrike: mv("blackoutStrike", 34, [cap([6, 10], 20, -70, 140, -60, 24, 10, 42, 50, 90, HEAVY)], strike(34, 6, 20), { counterStrike: true, invuln: [1, 8] }),
    ledgeAttack: mv("ledgeAttack", 40, [cap([12, 16], 10, -60, 100, -60, 20, 9, 45, 40, 65, CORD)], strike(40, 12, 14), { invuln: [1, 14] }),
    getupAttack: mv("getupAttack", 44, [cap([12, 15], 10, -40, 100, -40, 20, 7, 45, 40, 60, { ...CORD, group: 0 }), cap([20, 23], -10, -40, -100, -40, 20, 7, 45, 40, 60, { ...CORD, group: 1 })], [key(0, P({ rot: -80, dy: 20 })), key(12, P({ rot: 16 })), key(20, P({ rot: -16 })), key(44, rest)], { invuln: [1, 22] }),
    taunt: mv("taunt", 50, [], [key(0, rest), key(12, P({ rot: -14, sy: 1.1 })), key(26, P({ rot: 14, sy: 1.1 })), key(40, P({ sy: 0.94 })), key(50, rest)]),
  };

  return {
    id: "lampjack", // replaced by the forge with the player's fighter id
    name: "LAMPJACK",
    tagline: "A desk lamp with a grudge and a very long cord.",
    stats,
    moves,
    rig: { bones: [], anims: spriteAnims(), loops: spriteLoops },
    palette: { colors: { marker: "#c94a3c" }, accent: "marker", outline: "#292722" },
    // every key must exist from the start: the state hash walks these
    special: () => ({ charge: 0, heat: 0 }),
    hooks: {
      flash: ({ f, input }) => {
        // hold special on frames 1..24 to charge (up to 60 frames); the burst scales with it
        if (f.frame <= 24 && f.special.charge < 60 && (input.b & B.SPECIAL)) {
          f.special.charge++;
          if (f.frame === 24) f.frame = 23;
          return;
        }
        if (f.frame === 25) {
          f.chargeMul = 1 + (f.special.charge / 60) * 0.8;
          f.special.heat = Math.min(100, f.special.heat + 30 + f.special.charge / 2);
          f.special.charge = 0;
        }
      },
      cast: ({ f, state }) => {
        if (f.frame === 12) {
          // angle 180: the hit pulls the victim back toward the lamp
          spawnProjectile(state, f, "hook", f.x + f.moveFacing * 40, f.y - 70, f.moveFacing * 11, -1.5, 40,
            { frames: [0, 999], x: 0, y: 0, r: 16, damage: 6, angle: 180, base: 30, growth: 20, fx: "energy" }, { g: 0.18 });
        }
      },
      lift: ({ f, input }) => {
        if (f.frame === 4) { f.grounded = false; f.platform = -1; f.usedUpSpecial = true; }
        if (f.frame >= 4 && f.frame <= 34) {
          f.vy = -7 + (f.frame - 4) * 0.18;
          f.vx = (input.x / 100) * 3.2;
        }
      },
    },
    onFrame: ({ f }) => { if (f.special.heat > 0) f.special.heat -= 0.15; },
    meters: [{ label: "HEAT", color: "#ffb920", get: (f) => f.special.heat / 100 }],
    visual: (f) => ({ glow: f.special.heat / 100 }),
  };
}
